operation.add:
// Get what was returned
$curl_info = curl_getinfo($cr);

// In some cases, the primary_ip is not set by curl_getinfo, so we need to resolve it ourselves.
$forceCurl = (bool)($modSettings['forceCurl_enablesetting'] ?? 0);
$forceCurlRealIP = (bool)($modSettings['forceCurl_enablesetting_realip'] ?? 0);
if($forceCurl && $forceCurlRealIP) {
	// 1. We extract only the domain from the URL (e.g., download.simplemachines.org)
	$host = parse_url($curl_info['url'], PHP_URL_HOST);

	// 2. We use gethostbyname to resolve the domain to an IP address
	$curl_info['primary_ip'] = gethostbyname($host);

	// 3. If gethostbyname fails (returns the host string instead of an IP)
	if ($curl_info['primary_ip']=== $host) {
		// Try dns_get_record
		$records = @dns_get_record($host, DNS_A);

		if (!empty($records[0]['ip'])) {
			$curl_info['primary_ip'] = $records[0]['ip'];
		}
	}
}

